+type Task = {
+  id: string;
+  duration: number;
+  dependsOn: string[];
+};
+
+type Timing = {
+  start: number;
+  finish: number;
+};
+
+function fail(message: string): never {
+  throw new Error(message);
+}
+
+function compareSequences(left: string[], right: string[]): number {
+  const length = Math.min(left.length, right.length);
+  for (let index = 0; index < length; index++) {
+    const comparison = left[index].localeCompare(right[index]);
+    if (comparison !== 0) return comparison;
+  }
+  return left.length - right.length;
+}
+
+function parseTasks(value: unknown): Task[] {
+  if (typeof value !== "object" || value === null || Array.isArray(value)) {
+    return fail("input must be a JSON object");
+  }
+
+  const input = value as Record<string, unknown>;
+  if (!Array.isArray(input.tasks)) fail("tasks must be an array");
+
+  const tasks: Task[] = [];
+  const ids = new Set<string>();
+
+  for (let index = 0; index < input.tasks.length; index++) {
+    const raw = input.tasks[index];
+    const label = `tasks[${index}]`;
+    if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
+      fail(`${label} must be an object`);
+    }
+
+    const task = raw as Record<string, unknown>;
+    if (typeof task.id !== "string" || task.id.length === 0) {
+      fail(`${label}.id must be a non-empty string`);
+    }
+    if (ids.has(task.id)) fail(`duplicate task id: ${task.id}`);
+    ids.add(task.id);
+
+    if (
+      typeof task.duration !== "number" ||
+      !Number.isFinite(task.duration) ||
+      task.duration < 0
+    ) {
+      fail(`${label}.duration must be a finite non-negative number`);
+    }
+
+    const rawDependencies = task.dependsOn ?? [];
+    if (!Array.isArray(rawDependencies)) fail(`${label}.dependsOn must be an array`);
+
+    const dependsOn: string[] = [];
+    const dependencies = new Set<string>();
+    for (let dependencyIndex = 0; dependencyIndex < rawDependencies.length; dependencyIndex++) {
+      const dependency = rawDependencies[dependencyIndex];
+      if (typeof dependency !== "string") {
+        fail(`${label}.dependsOn[${dependencyIndex}] must be a string`);
+      }
+      if (dependencies.has(dependency)) {
+        fail(`${label}.dependsOn contains duplicate id: ${dependency}`);
+      }
+      dependencies.add(dependency);
+      dependsOn.push(dependency);
+    }
+
+    tasks.push({ id: task.id, duration: task.duration, dependsOn });
+  }
+
+  for (const task of tasks) {
+    for (const dependency of task.dependsOn) {
+      if (dependency === task.id) fail(`task ${task.id} cannot depend on itself`);
+      if (!ids.has(dependency)) fail(`task ${task.id} depends on unknown task: ${dependency}`);
+    }
+  }
+
+  return tasks;
+}
+
+function findCycle(tasks: Task[]): string[] | null {
+  const byId = new Map(tasks.map((task) => [task.id, task]));
+  const state = new Map<string, number>();
+  const stack: string[] = [];
+  const stackIndex = new Map<string, number>();
+
+  function visit(id: string): string[] | null {
+    state.set(id, 1);
+    stackIndex.set(id, stack.length);
+    stack.push(id);
+
+    const dependencies = [...byId.get(id)!.dependsOn].sort();
+    for (const dependency of dependencies) {
+      if (state.get(dependency) === 1) {
+        return [...stack.slice(stackIndex.get(dependency)), dependency];
+      }
+      if (!state.has(dependency)) {
+        const cycle = visit(dependency);
+        if (cycle) return cycle;
+      }
+    }
+
+    stack.pop();
+    stackIndex.delete(id);
+    state.set(id, 2);
+    return null;
+  }
+
+  for (const id of [...byId.keys()].sort()) {
+    if (!state.has(id)) {
+      const cycle = visit(id);
+      if (cycle) return cycle;
+    }
+  }
+  return null;
+}
+
+function plan(tasks: Task[]) {
+  const byId = new Map(tasks.map((task) => [task.id, task]));
+  const dependents = new Map<string, string[]>();
+  const remainingDependencies = new Map<string, number>();
+
+  for (const task of tasks) {
+    dependents.set(task.id, []);
+    remainingDependencies.set(task.id, task.dependsOn.length);
+  }
+  for (const task of tasks) {
+    for (const dependency of task.dependsOn) dependents.get(dependency)!.push(task.id);
+  }
+  for (const ids of dependents.values()) ids.sort();
+
+  const ready = tasks
+    .filter((task) => task.dependsOn.length === 0)
+    .map((task) => task.id)
+    .sort();
+  const order: string[] = [];
+
+  while (ready.length > 0) {
+    const id = ready.shift()!;
+    order.push(id);
+    for (const dependent of dependents.get(id)!) {
+      const remaining = remainingDependencies.get(dependent)! - 1;
+      remainingDependencies.set(dependent, remaining);
+      if (remaining === 0) {
+        ready.push(dependent);
+        ready.sort();
+      }
+    }
+  }
+
+  if (order.length !== tasks.length) {
+    const cycle = findCycle(tasks);
+    fail(`dependency cycle: ${cycle!.join(" -> ")}`);
+  }
+
+  const layers: string[][] = [];
+  const layerById = new Map<string, number>();
+  const earliest: Record<string, Timing> = {};
+  const criticalTo = new Map<string, string[]>();
+
+  for (const id of order) {
+    const task = byId.get(id)!;
+    let layer = 0;
+    let start = 0;
+    let predecessorPath: string[] | null = null;
+
+    for (const dependency of task.dependsOn) {
+      layer = Math.max(layer, layerById.get(dependency)! + 1);
+      const dependencyFinish = earliest[dependency].finish;
+      const path = criticalTo.get(dependency)!;
+      if (
+        dependencyFinish > start ||
+        (dependencyFinish === start &&
+          (predecessorPath === null || compareSequences(path, predecessorPath) < 0))
+      ) {
+        start = dependencyFinish;
+        predecessorPath = path;
+      }
+    }
+
+    layerById.set(id, layer);
+    (layers[layer] ??= []).push(id);
+    earliest[id] = { start, finish: start + task.duration };
+    criticalTo.set(id, [...(predecessorPath ?? []), id]);
+  }
+
+  for (const layer of layers) layer.sort();
+
+  let totalDuration = 0;
+  let criticalPath: string[] = [];
+  for (const id of order) {
+    const finish = earliest[id].finish;
+    const path = criticalTo.get(id)!;
+    if (
+      finish > totalDuration ||
+      (finish === totalDuration &&
+        (criticalPath.length === 0 || compareSequences(path, criticalPath) < 0))
+    ) {
+      totalDuration = finish;
+      criticalPath = path;
+    }
+  }
+
+  return { order, layers, earliest, totalDuration, criticalPath };
+}
+
+async function main(): Promise<void> {
+  const args = Bun.argv.slice(2);
+  if (args.length === 0) fail("usage: bun run src/cli.ts plan INPUT.json");
+  if (args[0] !== "plan") fail(`unknown command: ${args[0]}`);
+  if (args.length < 2) fail("missing input file");
+  if (args.length > 2) fail(`unknown argument or flag: ${args[2]}`);
+
+  let text: string;
+  try {
+    text = await Bun.file(args[1]).text();
+  } catch (error) {
+    fail(`cannot read input file: ${error instanceof Error ? error.message : String(error)}`);
+  }
+
+  let input: unknown;
+  try {
+    input = JSON.parse(text);
+  } catch (error) {
+    fail(`invalid JSON: ${error instanceof Error ? error.message : String(error)}`);
+  }
+
+  console.log(JSON.stringify(plan(parseTasks(input))));
+}
+
+main().catch((error) => {
+  console.error(error instanceof Error ? error.message : String(error));
+  process.exit(1);
+});
