import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
const dir = mkdtempSync(join(tmpdir(), "dependency-planner-"));
const cli = join(process.cwd(), "src/cli.ts");
function run(name, input, expected, expectedError) {
  const file = join(dir, `${name}.json`);
  writeFileSync(file, typeof input === "string" ? input : JSON.stringify(input));
  const result = Bun.spawnSync(["bun", "run", cli, "plan", file], { stdout: "pipe", stderr: "pipe" });
  const stdout = result.stdout.toString().trim();
  const stderr = result.stderr.toString().trim();
  if (expected !== undefined) {
    if (result.exitCode !== 0) throw new Error(`${name}: exit ${result.exitCode}: ${stderr}`);
    if (stdout !== JSON.stringify(expected)) throw new Error(`${name}: unexpected output\n${stdout}`);
  } else {
    if (result.exitCode === 0) throw new Error(`${name}: expected failure`);
    if (!stderr.includes(expectedError)) throw new Error(`${name}: unexpected stderr: ${stderr}`);
    if (stdout !== "") throw new Error(`${name}: emitted stdout on failure`);
  }
}
